package io.github.rebrowser.control;
import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.concurrent.atomic.*;
/** Actual native bounded reader; synthetic source/audience/input, no IPC/Android authority. */
public final class ControlResultStreamTest {
 static final class F {final AtomicReference<ComponentGate.SourceView> view=new AtomicReference<>(ComponentGate.SourceView.acceptedNative(this,new byte[16]));final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,view::get);final ComponentGate.DataEpochPin pin=gate.captureDataEpoch(gate.requireBusiness());final AtomicBoolean viewer=new AtomicBoolean(true);void audience(){if(!viewer.get())throw new SecurityException();}ControlResultStream stream(InputStream input,long max){return new ControlResultStream(input,pin,this::audience,max);}}
 @Test public void exactBoundNeedsActualEofSentinel()throws Exception{F f=new F();try(ControlResultStream s=f.stream(new ByteArrayInputStream(new byte[]{1,2}),2)){try(ControlResultStream.Chunk c=s.nextOwnedChunk()){assertEquals(2,c.borrowedReadOnly().remaining());assertFalse(c.actualEofObserved());}try(ControlResultStream.Chunk c=s.nextOwnedChunk()){assertTrue(c.actualEofObserved());assertEquals(0,c.borrowedReadOnly().remaining());}assertThrows(IllegalStateException.class,s::nextOwnedChunk);assertEquals(2,s.bytesReturned());}}
 @Test public void outstandingChunkBlocksNextUntilActualDisposal()throws Exception{F f=new F();try(ControlResultStream s=f.stream(new ByteArrayInputStream(new byte[]{4}),1)){ControlResultStream.Chunk c=s.nextOwnedChunk();assertThrows(IllegalStateException.class,s::nextOwnedChunk);c.close();assertTrue(s.nextOwnedChunk().actualEofObserved());}}
 @Test public void actualCloseScrubsPreviouslyBorrowedBytes()throws Exception{F f=new F();try(ControlResultStream s=f.stream(new ByteArrayInputStream(new byte[]{8}),1)){ControlResultStream.Chunk c=s.nextOwnedChunk();ByteBuffer b=c.borrowedReadOnly();assertTrue(b.isReadOnly());assertEquals(8,b.get(0));c.close();assertEquals(0,b.get(0));assertThrows(IllegalStateException.class,c::borrowedReadOnly);}}
 @Test public void overBoundByteIsNotReturnedAndStreamCannotRetry()throws Exception{F f=new F();try(ControlResultStream s=f.stream(new ByteArrayInputStream(new byte[]{1,2}),1)){assertThrows(IOException.class,s::nextOwnedChunk);assertEquals(0,s.bytesReturned());assertThrows(SecurityException.class,s::nextOwnedChunk);}}
 @Test public void zeroProgressDoesNotSpinOrFallBackToSingleByte()throws Exception{F f=new F();try(ControlResultStream s=f.stream(new InputStream(){public int read(){throw new AssertionError();}public int read(byte[] b,int o,int n){return 0;}},10)){assertThrows(IOException.class,s::nextOwnedChunk);assertThrows(SecurityException.class,s::nextOwnedChunk);}}
 @Test public void audienceRecheckedAfterActualRead()throws Exception{F f=new F();InputStream input=new InputStream(){public int read(){throw new AssertionError();}public int read(byte[] b,int o,int n){b[o]=9;f.viewer.set(false);return 1;}};try(ControlResultStream s=f.stream(input,1)){assertThrows(SecurityException.class,s::nextOwnedChunk);assertEquals(0,s.bytesReturned());}}
 @Test public void heldChunkCannotBeBorrowedAfterAudienceRevocation()throws Exception{F f=new F();try(ControlResultStream s=f.stream(new ByteArrayInputStream(new byte[]{3}),1)){ControlResultStream.Chunk c=s.nextOwnedChunk();f.viewer.set(false);assertThrows(SecurityException.class,c::borrowedReadOnly);c.close();}}
 @Test public void sourceCutoverRejectsHeldChunkEvenEqualEpoch()throws Exception{F f=new F();try(ControlResultStream s=f.stream(new ByteArrayInputStream(new byte[]{3}),1)){ControlResultStream.Chunk c=s.nextOwnedChunk();f.view.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));assertThrows(SecurityException.class,c::borrowedReadOnly);c.close();}}
 @Test public void detachIsNotInputCloseOrOwnerEnd()throws Exception{F f=new F();AtomicInteger closes=new AtomicInteger();InputStream in=new ByteArrayInputStream(new byte[]{2}){public void close(){closes.incrementAndGet();}};ControlResultStream s=f.stream(in,1);ControlResultStream.Chunk c=s.nextOwnedChunk();s.detachViewer();assertEquals(0,closes.get());assertThrows(SecurityException.class,c::borrowedReadOnly);s.close();assertEquals(1,closes.get());}
 @Test public void unknownCloseSpentOnceWithoutAlternateInput()throws Exception{F f=new F();AtomicInteger closes=new AtomicInteger();ControlResultStream s=f.stream(new InputStream(){public int read(){return -1;}public void close()throws IOException{closes.incrementAndGet();throw new IOException("synthetic");}},0);assertThrows(IOException.class,s::close);s.close();assertEquals(1,closes.get());}
 @Test public void rejectedConstructorClosesTransferredInputExactlyOnce(){F f=new F();f.viewer.set(false);AtomicInteger closes=new AtomicInteger();assertThrows(SecurityException.class,()->f.stream(new InputStream(){public int read(){return -1;}public void close(){closes.incrementAndGet();}},0));assertEquals(1,closes.get());}
 @Test public void audienceReentryCannotReviveOrDoubleRead()throws Exception{F f=new F();AtomicReference<ControlResultStream> ref=new AtomicReference<>();AtomicBoolean reenter=new AtomicBoolean(false);ControlResultStream s=new ControlResultStream(new ByteArrayInputStream(new byte[]{1}),f.pin,()->{if(reenter.get())assertThrows(SecurityException.class,()->ref.get().nextOwnedChunk());},1);ref.set(s);reenter.set(true);assertThrows(SecurityException.class,s::nextOwnedChunk);s.close();}
}
